import {StringReadOnlyExpression} from "./stringExpression";
import {NumberReadOnlyExpression} from "./numberExpression";
import {MaybeReadOnlyExpression} from "./maybeExpression";
import {ConditionReadOnlyExpression} from "./conditionExpression";
import {EntityReadOnlyExpression} from "../dataExpression/Entity";
import {NumberBlueprint} from "./numberBlueprint";

/**
 * A list-maker lambda: returns the set of templates (or sub-blueprints) the
 * blueprint is built over. Evaluated at generateValue()/isGeneratedBy() time so
 * the list can be produced dynamically (it can reach the live hostApi through
 * its enclosing scope).
 */
export type EntityBlueprintListMaker = () => Array<EntityTemplate | EntityBlueprint>;

/**
 * A template: the field maps an entity blueprint instantiates — it carries no id
 * (the caller supplies one at registration). Any `textMap` field may be a
 * concrete value or a {@link StringBlueprint}'s generateValue() grammar, so one
 * template can denote many concrete entities. A `numberMap` field may be a fixed
 * value or a {@link NumberBlueprint}'s generateValue() grammar.
 */
export type EntityTemplate = {
  textMap?: Record<string, StringReadOnlyExpression | string>;
  numberMap?: Record<string, NumberReadOnlyExpression | number | NumberBlueprint>;
}

/**
 * EntityBlueprint — a composable grammar over a set of entity templates. It
 * generates a random concrete entity from the union of its templates'
 * languages (drawn from the shared seeded LXM stream), instantiates it in the
 * world, and tests whether a given entity could have been generated by it. See
 * entityBlueprint.js.
 */
export type EntityBlueprintApi = {
  /**
   * Language = union of the templates' (or sub-blueprints') languages. Takes a
   * list-maker lambda `() => Array<template | subBlueprint>`, evaluated at
   * generateValue()/isGeneratedBy() time so the template set (and any generated
   * field values) can be produced dynamically.
   */
  oneOf: (makeList: EntityBlueprintListMaker) => EntityBlueprint;

  /** Marker for HostApi surfaces */
  type: EntityBlueprintType,
}

export type EntityBlueprintType = {
  // used when declaring argument types dynamically in HostApi clients
}

export type EntityBlueprint = {
  /**
   * Instantiates a new entity from a random concrete template (seeded LXM),
   * registers it in the world under a fresh id, and returns a read-only
   * {@link EntityReadOnlyExpression} over it. Present (maybe.of) when the
   * language is non-empty; absent (maybe.none) for oneOf([]).
   */
  generateValue: () => MaybeReadOnlyExpression<EntityReadOnlyExpression>;

  /**
   * Exact field membership as a condition: true iff `candidate`'s field maps
   * match a member of this blueprint's language (id is not considered).
   */
  isGeneratedBy: (candidate: EntityReadOnlyExpression | EntityTemplate) => ConditionReadOnlyExpression<EntityReadOnlyExpression>,
}
